public final class String {  // final prevents subclassing
    private final byte[] value;  // internal storage, final and private
    private int hash;  // cached hashCode

    public String(String original) {
        this.value = original.value;  // shares internal array safely
    }

    public String concat(String str) {
        // Never modifies this String, returns new object
        if (str.isEmpty()) return this;
        byte[] newValue = Arrays.copyOf(value, value.length + str.value.length);
        System.arraycopy(str.value, 0, newValue, value.length, str.value.length);
        return new String(newValue);  // new String instance
    }

    public int hashCode() {
        if (hash == 0 && value.length > 0) {
            hash = computeHash();  // compute once
        }
        return hash;  // return cached value
    }
}

public class ReportGenerator {
    // SLOW: O(N²) — creates 10,000 String objects
    public String generateReportSlow(List<String> entries) {
        var report = "Report:\n";
        for (var entry : entries) {  // 10,000 iterations
            report = report + entry + "\n";  // copies all characters every time
        }
        return report;
    }

    // FAST: O(N) — single mutable buffer
    public String generateReportFast(List<String> entries) {
        var builder = new StringBuilder("Report:\n");
        for (var entry : entries) {
            builder.append(entry).append("\n");  // appends in-place
        }
        return builder.toString();  // single copy at the end
    }

    // Modern Java optimizes this automatically (no loop)
    public String simpleConcat(String a, String b, String c) {
        return a + b + c;  // compiles to StringBuilder internally
    }
}

public final class UserReport {  // final prevents subclassing
    private final String username;
    private final LocalDate generatedOn;
    private final List<String> entries;  // mutable type

    public UserReport(String username, LocalDate generatedOn, List<String> entries) {
        this.username = username;
        this.generatedOn = generatedOn;  // LocalDate is already immutable
        this.entries = List.copyOf(entries);  // defensive copy, makes unmodifiable
    }

    public String getUsername() {
        return username;  // String is immutable, safe to return
    }

    public List<String> getEntries() {
        return entries;  // already unmodifiable from constructor, safe
    }
}

