public final class String {
    private final byte[] value;  // character data
    private int hash;  // cached hashCode, default 0

    public int hashCode() {
        int h = hash;  // read cached value
        if (h == 0 && value.length > 0) {  // not yet computed
            h = computeHashCode();  // expensive: iterates all chars
            hash = h;  // store for future calls
        }
        return h;
    }

    private int computeHashCode() {
        int h = 0;
        for (byte v : value) {
            h = 31 * h + v;  // 31 is prime, good distribution
        }
        return h;
    }
}

// Usage in HashMap
public class UserCache {
    private final Map<String, User> usersByEmail = new HashMap<>();

    public void addUser(User user) {
        usersByEmail.put(user.getEmail(), user);  // hashCode called once
    }

    public User findUser(String email) {
        return usersByEmail.get(email);  // cached hash, instant lookup
    }
}

